const {F,T,X,S,G,D}=require('../author.cjs');
const equity=require('./equity-factors.cjs');
const shared=(id,objectives)=>{
 const s=structuredClone(equity.sections.find(s=>s.id===id));
 if(id==='risk-decomposition'){
  s.blocks.find(b=>b.kind==='example').given+=' Für genau diese beiden Vergleichsaktien gelten ein sicherer Jahreszins von drei Prozent und eine erwartete Marktprämie von fünf Prozentpunkten; dies ist ein eigener Eingabesatz.';
  s.blocks.find(b=>b.kind==='formula').symbols.push(['\\beta_i,\\sigma_M','Marktbeta der Anlage i und Marktstandardabweichung derselben Periode.'],['i','Index der jeweils betrachteten Anlage.']);
 }
 if(id==='excess')s.blocks.find(b=>b.kind==='formula').symbols.push(['i,t','Anlagen- und Zeitindex.']);
 if(id==='market-model'){const f=s.blocks.filter(b=>b.kind==='formula')[1];f.symbols[0][1]='Erwartete Rendite der Anlage i und des Marktes für dieselbe Zukunftsperiode.';f.symbols[1][1]='Intercept der Roh-Rendite und Steigung gegenüber dem Markt; beide werden für die Prognoseperiode als geeignet angenommen.';}
 return {...s,title:s.title.replace(/^\d+\. /,''),objectives:objectives.split(' ')};
};
const grid=(a,b,n,f)=>Array.from({length:n+1},(_,i)=>{const x=a+(b-a)*i/n;return[x,f(x)];});
const plot=(id,title,caption,reading,x,y,xLabel,yLabel,series,marks=[])=>G({id,title,caption,reading,plot:{x,y,xLabel,yLabel,series,marks}});
module.exports={id:'portfolio-pricing',intro:[
 'Eine hohe Rendite beantwortet noch nicht, ob eine Anlage das eingegangene Risiko angemessen vergütet hat. CAPM, Marktmodell und Performancemaße stellen verschiedene Fragen. Dieses Kapitel leitet ihre Beziehungen her und zeigt ausdrücklich, wann ihre Urteile auseinandergehen dürfen.',
 'CFA Level I 2027, Portfolio Risk and Return: Part II, neun Lernziele. Zentrale eigene Vergleichsannahmen: sicherer Jahreszins drei Prozent, erwartete Marktrendite neun Prozent und Marktvolatilität zwanzig Prozent. Fonds P wird mit zehn Prozent Rendite, fünfundzwanzig Prozent Volatilität und Beta 1,1 analysiert. Die zehn Prozent sind eine eigene abweichende Analyseannahme, keine zugleich als CAPM-Gleichgewicht behauptete Rendite. Weitere klar bezeichnete Beispielsätze besitzen jeweils eigene Eingaben; alle Daten und Portfolios sind fiktiv.',
 'Renditen in Formeln sind grundsätzlich Dezimalzahlen und gehören zum gleichen Horizont und zur gleichen Währung. Im Labor werden Renditen als Prozentwerte eingegeben. Herleitungen und statistische Vertiefungen erleichtern das Verständnis, erweitern aber nicht den offiziellen Lernzielkatalog.'
],sections:[
 S('map','Welche Frage beantwortet welches Modell?','a b c d e f g h i',[
  T(['Instrument','Frage','Für die Interpretation nötig'],[['CAL und CML','Welche Kombination aus sicherer und riskanter Anlage ist erreichbar?','Finanzierungssätze, zulässige Gewichte und Bedeutung des riskanten Portfolios.'],['Marktmodell','Wie verändert sich eine Rendite mit einem beobachteten Marktfaktor?','Regressionskonvention, Zeitraum, Daten und unerklärter Rest.'],['CAPM und SML','Welche erwartete Vergütung fordert das Gleichgewichtsmodell für Marktbeta?','Gemeinsame Erwartungen, Marktportfolio und weitere Modellannahmen.'],['Sharpe und M²','Wie ist die Überschussrendite im Verhältnis zum Gesamtrisiko?','Passender sicherer Zins, Streuung der Überschussrendite und Risikoangleichung.'],['Treynor und Jensen','Wie ist die Rendite relativ zum Marktbeta zu beurteilen?','Sinnvoller Marktbezug, Beta und Residualrisiko des gehaltenen Gesamtportfolios.']],'Die Maße sind keine austauschbaren Namen für dieselbe Rendite.'),
  'Vor jeder Rechnung werden erwartete Größen von historischen Schätzungen und realisierten Einzelergebnissen getrennt. Eine schöne historische Kennzahl ist kein Beweis einer zukünftigen Prämie oder eines dauerhaft geschickten Managers.'
 ]),
 S('risk-free','Risikofrei heißt sicher für den betrachteten Anspruch','a',[
  'Für einen in Euro gemessenen Jahresendwert muss die sichere Anlage genau diesen Euro-Endwert sichern. Eine sichere Dollarzahlung ist in Euro wechselkursabhängig. Eine ausfallsichere lange Anleihe ist beim Verkauf vor Fälligkeit zinsabhängig. Nominale Sicherheit garantiert keine reale Kaufkraft.',
  'Das Grundmodell unterstellt, dass der sichere Periodenertrag nicht zufällig ist. Dadurch sind seine Varianz und seine Kovarianz mit jeder riskanten Rendite null. In einer historischen Mehrperiodenstichprobe können die damals verfügbaren Geldmarktsätze dagegen von Monat zu Monat verschieden sein. Diese Unterscheidung wird später für die Sharpe-Berechnung wichtig.'
 ]),
 S('combinations','Cash und Marktportfolio aus den Anfangsgewichten herleiten','a b',[
  F('R_C=(1-y)r_f+yR_M,\\quad\\mu_C=r_f+y(\\mu_M-r_f),\\quad\\sigma_C=|y|\\sigma_M','Gewichte werden auf das anfängliche Nettovermögen bezogen. Die sichere Komponente trägt zum Ertrag, aber nicht zur Varianz des betrachteten Zeitraums bei.',[['R_C,R_M','Zufällige einfache Periodenrenditen des Gesamtportfolios und der riskanten Marktanlage.'],['\\mu_C,\\mu_M','Ihre erwarteten Renditen.'],['r_f','Sicherer Periodenzins, im Grundmodell auch Kreditzins.'],['y','Anfangsgewicht der riskanten Anlage; Cashgewicht ist 1 − y.'],['\\sigma_C,\\sigma_M','Standardabweichungen; der Betrag berücksichtigt auch ein negatives y.']]),
  X('Nur das riskante Gewicht verändern','Markterwartung neun Prozent, Marktvolatilität zwanzig Prozent und sicherer Zins drei Prozent; gleicher Anlage- und Kreditzins, Kosten zunächst null.',[
   T(['Marktgewicht y','Cashgewicht','Erwartete Rendite','Standardabweichung'],[['−0,5','1,5','0 %','10 %'],['0','1','3 %','0 %'],['0,5','0,5','6 %','10 %'],['1','0','9 %','20 %'],['1,5','−0,5','12 %','30 %']],'Negative Gewichte verlangen erlaubte Shortpositionen beziehungsweise Kreditaufnahme; sie sind keine kostenlose automatische Handlungsmöglichkeit.'),
   F('\\mu_C(0{,}5)=0{,}03+0{,}5(0{,}09-0{,}03)=0{,}06,\\quad\\sigma_C(0{,}5)=0{,}10','Bei halber Risikoanlage werden Ertragsprämie und Schwankung halbiert. Der sichere Anteil verdient weiterhin den sicheren Zins.',[['\\mu_C(y),\\sigma_C(y)','Erwartete Rendite und Standardabweichung beim in Klammern genannten Marktgewicht.']]),
   'Mehr erwartete Rendite durch Hebelung bedeutet zugleich größere Schwankungen und mögliche Finanzierungsprobleme. Ein höherer erwarteter Ertrag macht die Strategie nicht risikofrei.'
  ],'Rendite ist linear in den Gewichten; Varianz wächst quadratisch und Standardabweichung mit dem Betrag des riskanten Gewichts.')
 ]),
 S('financing','Ein Kreditzins oberhalb des Anlagesatzes erzeugt einen Knick','a b',[
  F('\\mu_C=y\\mu_M-(y-1)r_b\\quad(y>1)','Nach vollständigem Einsatz des Eigenkapitals wird zusätzliche Risikoanlage zum tatsächlich geltenden Kreditzins finanziert.',[['\\mu_C,\\mu_M','Erwartete Gesamt- und Marktrendite.'],['y','Marktgewicht oberhalb eins.'],['r_b','Kreditzins derselben Periode; er muss nicht dem sicheren Anlagesatz entsprechen.']]),
  X('Gleiche Exposition, andere Finanzierung','Je hundert Eigenkapital werden fünfzig geliehen; insgesamt hundertfünfzig werden riskant angelegt. Die Markterwartung bleibt neun Prozent.',[
   F('\\mu_C=1{,}5(0{,}09)-0{,}5(0{,}03)=12\\%,\\quad\\mu_C^{b}=1{,}5(0{,}09)-0{,}5(0{,}05)=11\\%','Fünf statt drei Prozent Kreditzins kosten auf den halben geliehenen Eigenkapitalbetrag einen zusätzlichen Prozentpunkt erwartete Eigenkapitalrendite.',[['\\mu_C,\\mu_C^{b}','Erwartete Rendite bei Kredit zum sicheren Satz beziehungsweise zum höheren Kreditsatz.']]),
   'Die Marktvolatilität der Position ist in beiden Rechnungen dreißig Prozent. Die Finanzierung verändert hier den Ertrag, nicht die vorausgesetzte Zufallsbewegung der Marktanlage. Tatsächliche Margin Calls und erzwungene Verkäufe können darüber hinaus die Strategie verändern.'
  ],'Eine einzige durchgehende CAL setzt die passenden identischen Finanzierungssätze voraus.')
 ]),
 S('cal','Die Steigung der Kapitalallokationslinie verstehen','a b',[
  F('\\mu_C=r_f+\\frac{\\mu_P-r_f}{\\sigma_P}\\sigma_C\\quad(y\\ge0)','Für ein festes riskantes Portfolio P eliminiert man das nichtnegative Risikogewicht aus Rendite- und Risikogleichung. Die Steigung ist dessen erwartete Sharpe Ratio.',[['\\mu_C,\\mu_P','Erwartete Renditen der vollständigen Mischung und des riskanten Portfolios.'],['r_f','Sicherer gemeinsamer Anlage- und Kreditzins.'],['\\sigma_C,\\sigma_P','Standardabweichungen der Gesamtmischung und des Fonds; die Fondsstreuung ist positiv.'],['y','Nichtnegatives Gewicht der riskanten Anlage.']]),
  plot('allocation-lines','Gleiches Gesamtrisiko, unterschiedliche erwartete Rendite','Eigene Markt-Cash-Linie mit 9 % Rendite und 20 % Risiko sowie Fonds-Cash-Linie mit 10 % Rendite und 25 % Risiko. Sicherer Zins 3 %, reibungslose Skalierung.','Der Fonds hat die höhere eigene Rendite, aber die flachere Cash-Linie. Bei zwanzig Prozent Risiko erreicht die Fonds-Cash-Mischung 8,6 Prozent statt neun. Die Marktlinie darf nur unter den CAPM-Gleichgewichtsannahmen CML genannt werden.',[0,40],[0,16],'Gesamtstandardabweichung (%)','Erwartete Rendite (%)',[
   {name:'Markt und Cash: Steigung 0,30',points:grid(0,40,80,s=>3+.30*s)},
   {name:'Fonds P und Cash: Steigung 0,28',points:grid(0,40,80,s=>3+.28*s),dash:true}
  ])
 ]),
 S('cml','Von einer beliebigen CAL zur CML','b f',[
  'Jedes riskante Portfolio hat unter den entsprechenden Cash-Annahmen seine eigene CAL. Eine hohe positive Steigung ist für die Wahl eines einzelnen riskanten Fonds neben Cash attraktiv. Der Anteil am ausgewählten Fonds wird anschließend von Risikoaversion und Grenzen bestimmt.',
  'Im klassischen CAPM teilen Anleger dieselben relevanten Erwartungen, wählen nach Mittelwert und Varianz und haben Zugang zu einem gemeinsamen sicheren Finanzierungssatz. Unter den weiteren Markt- und Gleichgewichtsannahmen wird das gemeinsame Tangentialportfolio zum Marktportfolio aller relevanten riskanten Vermögenswerte. Seine Cash-Linie heißt Capital Market Line.',
  'Diese Schlussfolgerung ist modellabhängig. Verschiedene Erwartungen, Finanzierungspreise, Steuer- oder Handelsgrenzen können verschiedene riskante Portfolios rechtfertigen. Eine vorhandene Aktie, ein einzelner Hedgefonds oder ein beliebiger Index ist nicht durch seine Bezeichnung schon das effiziente Marktportfolio.'
 ]),
 shared('co-risk','c'),shared('risk-decomposition','c d e'),shared('diversification','c'),
 shared('market-model','d'),shared('excess','d i'),
 S('beta','Beta ist eine Kovarianzgröße und keine bloße Volatilität','c e',[
  F('\\beta_P=\\frac{\\operatorname{Cov}(R_P,R_M)}{\\sigma_M^2}=\\rho_{PM}\\frac{\\sigma_P}{\\sigma_M}','Die Division der gemeinsamen Streuung durch die positive Marktvarianz misst die lineare Marktsensitivität. Korrelation allein und Gesamtvolatilität allein reichen jeweils nicht aus.',[['\\beta_P','Marktbeta von P, dimensionslos.'],['R_P,R_M','Renditen gleicher Periode, Währung und Messkonvention.'],['\\rho_{PM}','Korrelation zwischen P und Markt.'],['\\sigma_P,\\sigma_M','Positive Portfolio- und Marktstandardabweichungen.'],['\\operatorname{Cov}','Kovarianz.']]),
  X('Den zentralen Fondsfall auf Konsistenz prüfen','P hat Volatilität 25 % und Beta 1,1, der Markt Volatilität 20 %. Ein Einindexrest wird als mit dem Markt unkorreliert angenommen.',[
   F('\\operatorname{Cov}(R_P,R_M)=1{,}1(0{,}20)^2=0{,}044,\\quad\\rho_{PM}=\\frac{1{,}1(0{,}20)}{0{,}25}=0{,}88','Die Kovarianz folgt aus dem Beta, die Korrelation anschließend aus beiden Volatilitäten. Sie liegt im zulässigen Bereich.',[['R_P,R_M','Zufällige Fonds- und Marktrenditen.'],['\\rho_{PM}','Daraus folgende Korrelation.'],['\\operatorname{Cov}','Kovarianz in quadrierten Dezimalrenditeeinheiten.']]),
   F('\\sigma_{\\varepsilon}^2=0{,}25^2-1{,}1^2(0{,}20)^2=0{,}0141,\\quad\\sigma_{\\varepsilon}=\\sqrt{0{,}0141}\\approx11{,}8743\\%','Von der gesamten Varianz 0,0625 werden 0,0484 Marktfaktorvarianz abgezogen. Der positive Rest ist eine Varianz; erst seine Wurzel ist eine Volatilität.',[['\\sigma_{\\varepsilon}^2,\\sigma_{\\varepsilon}','Residualvarianz und Residualstandardabweichung im angegebenen Einindexmodell.']]),
   F('R^2=\\frac{1{,}1^2(0{,}20)^2}{0{,}25^2}=0{,}7744=\\rho_{PM}^2','77,44 Prozent der Varianz stammen im Modell aus dem Marktfaktor. Der verbleibende Anteil ist nicht automatisch harmloses oder vollständig unabhängiges ökonomisches Risiko.',[['R^2','Erklärter Varianzanteil beim passenden einfachen Einindexmodell mit unkorreliertem Rest.'],['\\rho_{PM}','Fonds-Marktkorrelation.']])
  ],'Die Eingaben sind gemeinsam möglich, weil die Restvarianz nicht negativ wird. Ein frei gewähltes Beta darf bei gegebenen Volatilitäten diese Bedingung nicht verletzen.')
 ]),
 shared('observations','d e'),shared('ols','d e'),shared('fit','d e'),
 S('portfolio-beta','Portfolio-Beta folgt aus der Linearität der Kovarianz','e',[
  F('\\beta_C=\\frac{\\operatorname{Cov}(\\sum_iw_iR_i,R_M)}{\\sigma_M^2}=\\sum_iw_i\\beta_i','Bei festen Anfangsgewichten und derselben Marktdefinition ist das Portfoliobeta die gewichtete Summe der Einzelbetas. Eine sichere Komponente besitzt Beta null.',[['\\beta_C,\\beta_i','Beta des Portfolios und der einzelnen Anlagen.'],['w_i','Anfangsgewicht von Anlage i.'],['R_i,R_M','Anlage- und Marktrendite.'],['\\sigma_M^2','Positive Marktvarianz.'],['i','Anlagenindex.'],['\\operatorname{Cov}','Kovarianz.']]),
  X('Cash verändert Beta und Gesamtrisiko gleichzeitig','Achtzig Prozent werden im zentralen Fonds P, zwanzig Prozent sicher gehalten.',[
   F('\\beta_C=0{,}8(1{,}1)=0{,}88,\\quad\\sigma_C=0{,}8(0{,}25)=0{,}20,\\quad\\mu_C=0{,}03+0{,}8(0{,}10-0{,}03)=0{,}086','Die Mischung erreicht genau die Marktvolatilität. Ihr Beta ist dennoch nicht eins, weil ein Teil des Fondsrisikos aus dem Rest stammt.',[['\\beta_C','Beta der Cash-Fonds-Mischung.'],['\\sigma_C','Gesamtstandardabweichung dieser Mischung.'],['\\mu_C','Ihre erwartete Rendite unter der eigenen Fondsannahme.']])
  ],'Gleiches Gesamtrisiko bedeutet nicht automatisch gleiches systematisches Risiko.')
 ]),
 S('beta-limits','Negatives Beta, Beta null und Schätzgrenzen','e f g',[
  'Negatives Beta bedeutet negative lineare Kovarianz mit dem gewählten Markt. Bei positiver erwarteter Marktrisikoprämie liegt die CAPM-Renditeforderung dann unter dem sicheren Zins. Das kann mit einem wertvollen Schutzbeitrag vereinbar sein; weder Gesamtvolatilität noch Verlustrisiko müssen null sein.',
  F('\\beta_i=0\\not\\Longrightarrow\\sigma_i=0,\\qquad|\\beta_i|\\sigma_M\\le\\sigma_i','Beta null beseitigt nur die lineare Markt-Kovarianz. Die zweite Beziehung folgt aus einer Korrelation mit Betrag höchstens eins und ist eine Konsistenzgrenze.',[['\\beta_i','Beta einer Anlage gegenüber demselben Markt.'],['\\sigma_i,\\sigma_M','Anlage- und positive Marktstandardabweichung.']]),
  'Bei Marktvarianz null ist Beta über die Kovarianzformel nicht definiert. Beta ist außerdem kein festes Naturmerkmal: Datenfrequenz, Schätzfenster, Indexwahl, Ausreißer und ein verändertes Geschäftsmodell können die Schätzung beeinflussen. Eine Standardabweichung von dreißig Prozent darf nicht als Beta 0,30 ausgegeben werden.'
 ]),
 shared('assumptions','f'),
 S('capm','Die CAPM-Renditeforderung aus Marktrisiko lesen','f g',[
  F('k_P=r_f+\\beta_P(\\mu_M-r_f)','Der sichere Zins vergütet die zeitliche Bindung. Das Marktbetarisiko multipliziert die erwartete Marktrisikoprämie. Im CAPM-Gleichgewicht entspricht k_P der erwarteten Rendite; eine eigene Analyseprognose kann davon abweichen.',[['k_P','Geforderte erwartete Periodenrendite im CAPM.'],['r_f','Sicherer Satz passender Währung und Periode.'],['\\beta_P','Marktbeta des betrachteten Anspruchs.'],['\\mu_M','Erwartete Marktrendite desselben Zeitraums.']]),
  X('Die erwartete Marktrendite ist nicht selbst die Prämie','Sicherer Satz drei Prozent, erwarteter Markt neun Prozent; Betas werden bei sonst gleichen Annahmen verändert.',[
   F('k(0)=3\\%,\\quad k(0{,}5)=6\\%,\\quad k(1)=9\\%,\\quad k(1{,}1)=9{,}6\\%,\\quad k(-0{,}5)=0\\%','Sechs Prozentpunkte erwartete Prämie werden pro Betaeinheit vergütet. Beta null ist nicht dasselbe wie Gesamtvolatilität null.',[['k(\\beta)','CAPM-Renditeforderung beim in Klammern eingesetzten Beta.']]),
   'Der negative Beta-Fall kann im Modell als Schutzbeitrag eine niedrigere erwartete Rendite tragen. Ein tatsächliches schlechtes Jahr ist dennoch möglich; lineare Gegenbewegung ist keine vollständige Verlustversicherung.'
  ],'Historische Marktrendite, erwartete Marktrendite und erwartete Marktrisikoprämie dürfen nicht vertauscht werden.')
 ]),
 S('sml','Die SML verbindet erwartete Rendite und Beta','f g h',[
  plot('pricing-line','Eine eigene Prognose über der SML ist eine These','Eigene Jahresannahmen: sicher 3 %, Markt 9 %. Die SML hat daher Steigung sechs Prozentpunkte pro Beta. P wird außerhalb des Gleichgewichtsvergleichs mit 10 % erwartet.','Bei Beta 1,1 fordert die Linie 9,6 Prozent. Der Abstand von P ist positives Analyse-Alpha von 0,4 Prozentpunkten. Das setzt eine tragfähige Prognose und passende Risikoeingaben voraus; ein realisierter guter Ertrag ist kein solcher Beweis.',[-.5,2],[0,16],'Marktbeta','Erwartete Rendite (%)',[{name:'CAPM-Renditeforderung',points:grid(-.5,2,100,b=>3+6*b)}],[{x:1,y:9,label:'Markt',dx:-12,anchor:'end',dy:18},{x:1.1,y:10,label:'Prognose P',dx:12,dy:-16}]),
  'Unterbewertung über der SML ist eine bedingte Interpretation: Gegebene plausible erwartete Zahlungen und ein zu niedriger aktueller Preis erzeugen eine höhere erwartete Rendite. Andere Erklärungen sind eine zu optimistische Zahlungsprognose, ein ungeeigneter Marktindex oder ein unterschätztes Beta. Die Rechnung entdeckt keine risikolose Arbitrage.'
 ]),
 S('cml-sml','CML und SML benutzen verschiedene horizontale Achsen','b f h',[
  T(['Vergleich','CML','SML'],[['Horizontale Größe','Gesamtstandardabweichung','Marktbeta'],['Betrachtete Anlagen','Effiziente Cash-Markt-Mischungen unter den Modellannahmen','Einzelanlagen und Portfolios im CAPM'],['Steigung','Erwartete Marktprämie je Marktstandardabweichung','Erwartete Marktprämie je Betaeinheit'],['Eine konzentrierte Aktie','Muss nicht auf der CML liegen','Wird nach ihrem Beta eingeordnet']],'Zwei Anlagen mit gleichem Beta können unterschiedliches Gesamtrisiko besitzen.'),
  X('Warum der zentrale Fonds zwei verschiedene Abstände hat','P wird mit 10 % Rendite, 25 % Volatilität und Beta 1,1 analysiert. Die Markt-Cash-Linie besitzt Steigung 0,30.',[
   F('\\mu_{MC}(0{,}25)=0{,}03+0{,}30(0{,}25)=10{,}5\\%,\\qquad k_P=9{,}6\\%','Die Cash-Markt-Mischung beim gleichen Gesamtrisiko liegt über P; die CAPM-Forderung beim gleichen Beta liegt darunter.',[['\\mu_{MC}(\\sigma)','Erwartete Rendite der Markt-Cash-Linie beim angegebenen Gesamtrisiko.'],['k_P','CAPM-Renditeforderung für P beim gegebenen Beta.']]),
   'Der Vergleich ist kein logischer Widerspruch: Die erste Linie beurteilt Gesamtvolatilität, die zweite Marktkovarianz. Die eigene P-Prognose mit positivem Alpha ist außerdem ausdrücklich eine Abweichung vom behaupteten CAPM-Gleichgewicht. Unter dieser alternativen Prognose ist die Markt-Cash-Linie nicht als tatsächlich effiziente Grenze bewiesen.'
  ],'Ein Modellpunkt wird zuerst nach Achse, Frage und Annahmen eingeordnet.')
 ]),
 S('valuation','CAPM in Auswahl und Bewertung anwenden','g h',[
  F('\\mu_P^{A}-k_P=\\alpha_P^{A}','Eine eigene erwartete Rendite über der geforderten Rendite ist positives Analyse-Alpha. Das ist eine überprüfbare Prognosedifferenz, keine bereits erwirtschaftete Auszahlung.',[['\\mu_P^{A}','Eigene erwartete Rendite unter der Analyseannahme A.'],['k_P','CAPM-Renditeforderung bei passenden Eingaben.'],['\\alpha_P^{A}','Daraus folgende erwartete Abweichung in Renditeeinheiten.']]),
  X('Prognose, Renditeforderung und tatsächlich eingetretenen Ertrag trennen','Ein Anteil kostet heute hundert. Erwartete gesamte Zahlung aus Verkauf und Ausschüttung in einem Jahr ist hundertzehn. Beta ist 1,1; sicher drei Prozent und erwarteter Markt neun Prozent.',[
   F('\\mu_P^{A}=110/100-1=10\\%,\\quad k_P=3\\%+1{,}1(9\\%-3\\%)=9{,}6\\%,\\quad\\alpha_P^{A}=0{,}4\\%','Die Differenz beträgt 0,4 Prozentpunkte. Sie entsteht aus der eigenen Zahlungsannahme und der modellierten Risikoforderung.',[['\\mu_P^{A}','Eigene erwartete Jahresrendite beim heutigen Preis.'],['k_P','CAPM-Renditeforderung.'],['\\alpha_P^{A}','Erwartetes Analyse-Alpha; Prozentdarstellung einer Renditedifferenz.']]),
   'Wird am Ende nur fünfundneunzig ausgezahlt, beträgt die tatsächliche Rendite minus fünf Prozent. Das widerlegt nicht durch einen einzigen Ausgang jede Erwartungsthese, zeigt aber, warum erwartetes Alpha keine Garantie ist. Für eine historische Performancebeurteilung sind gleichzeitige Markt- und Zinsdaten sowie eine angemessene Stichprobe nötig.'
  ],'Bewertung benötigt eine begründete Zahlungsanalyse und eine begründete Risikoforderung; eine einzelne Kennzahl ersetzt keine von beiden.'),
  D('Zusatzherleitung: Wenn der Preis sich ändert, kann sich auch Beta ändern',[
   F('\\beta_i=\\frac{\\operatorname{Cov}(X_i,R_M)}{P_{i,0}\\sigma_M^2},\\qquad P_{i,0}=\\frac{E[X_i]-\\frac{\\operatorname{Cov}(X_i,R_M)}{\\sigma_M^2}(\\mu_M-r_f)}{1+r_f}','Für einen einperiodigen Anspruch ist die Rendite Zahlung geteilt durch Anfangspreis minus eins. Setze diese Identität und das zugehörige Beta in das CAPM ein, multipliziere mit dem Preis und löse nach dem Preis auf. Der Marktprozess wird hier als vorgegeben behandelt.',[['X_i','Unsichere gesamte Endzahlung, einschließlich Endverkaufswert und Ausschüttung.'],['P_{i,0}','Positiver Anfangspreis.'],['R_M,\\mu_M,\\sigma_M^2','Zufällige Marktrendite, ihre Erwartung und positive Varianz.'],['r_f','Sicherer Periodenzins.'],['\\beta_i','Beta des Anspruchs beim jeweiligen Anfangspreis.'],['E[\\cdot],\\operatorname{Cov}','Erwartungswert und Kovarianz.']]),
   'Beim Anfangspreis hundert und Beta 1,1 ist die Auszahlung-Marktkovarianz 4,4 in Geld mal Renditeeinheiten. Mit erwarteter Zahlung hundertzehn ergibt die Konsistenzrechnung einen Preis von rund 100,38835. Sein Beta beträgt rund 1,095745. Wer stattdessen einen Diskontsatz als von außen fest vorgegeben annimmt, beantwortet eine andere Bewertungsannahme. Für mehrperiodige Unternehmensmodelle müssen Anspruch, Cashflows und Kapitalkosten gemeinsam konsistent sein.'
  ])
 ]),
 S('project-risk','Ein Projekt braucht die Renditeforderung seines eigenen Risikos','g h',[
  'Der durchschnittliche Firmen-Beta ist nicht automatisch die richtige Hürde für jedes Projekt. Ein risikoärmeres Geschäft kann bei einem unternehmensweit zu hohen Satz zu Unrecht verworfen werden. Ein riskanteres Projekt kann bei einem zu niedrigen Satz scheinbar attraktiv wirken.',
  X('Einheitliche Hürde, verschiedene wirtschaftliche Risiken','Eigene einjährige unverschuldete Projekte kosten jeweils hundert. Erwartete Endzahlung ist jeweils hundertacht. Zum didaktischen Vergleich werden risikogerechte erwartete Sätze sechs beziehungsweise zwölf Prozent vorgegeben.',[
   F('NPV_A=-100+\\frac{108}{1{,}06}\\approx1{,}8868,\\quad NPV_B=-100+\\frac{108}{1{,}12}\\approx-3{,}5714','Dieselbe erwartete Zahlung wird je nach passendem Risikopreis unterschiedlich bewertet. Die unterschiedlichen Sätze sind hier explizite Inputs, keine aus dem Endbetrag allein abgeleiteten Eigenschaften.',[['NPV_A,NPV_B','Kapitalwerte der zwei eigenen Projekte in Geldeinheiten.']]),
   'Aus CAPM-Eigenkapitalrendite darf nicht ohne Weiteres ein Satz für unverschuldete Gesamtunternehmenscashflows gemacht werden. Finanzierung und Anspruchsebene müssen passen; WACC und die Trennung von Geschäfts- und Finanzierungsrisiko werden in den zugehörigen Kapiteln erläutert.'
  ],'Ein Hürdensatz ist eine Risikoforderung, kein vorhergesagter interner Projektzins.')
 ]),
 S('sharpe','Sharpe: Überschussrendite je Einheit Gesamtstreuung','i',[
  F('D_t=R_{P,t}-R_{f,t},\\quad S_P=\\frac{E[D]}{\\sigma_D},\\quad\\widehat S_P=\\frac{\\bar D}{s_D}','Die allgemeine Berechnung verwendet Mittelwert und Standardabweichung derselben Differenzrendite. Erwartete Größen gehören zur Planung, historische Stichprobengrößen zur Rückschau.',[['D_t,D','Überschussrendite von P gegenüber dem sicheren Vergleich in Periode t beziehungsweise als Zufallsvariable.'],['R_{P,t},R_{f,t}','Zeitlich passende Fonds- und Vergleichsrendite.'],['S_P,\\widehat S_P','Erwartete und historische Sharpe Ratio.'],['E[D],\\bar D','Erwartungswert beziehungsweise arithmetischer Stichprobenmittelwert.'],['\\sigma_D,s_D','Positive vorausgesetzte beziehungsweise geschätzte Standardabweichung der Differenzrendite.'],['t','Zeitindex.']]),
  F('S_P=\\frac{\\mu_P-r_f}{\\sigma_P}\\quad\\text{bei konstantem }r_f','Ist der sichere Satz im betrachteten Modell konstant, verändert sein Abzug die Varianz nicht. Dann darf die Standardabweichung der Fondsrendite im Nenner stehen.',[['S_P','Sharpe Ratio.'],['\\mu_P,r_f','Erwartete Fondsrendite und konstanter sicherer Satz.'],['\\sigma_P','Positive Fondsstandardabweichung derselben Periode.']]),
  X('Zehn Prozent Rendite sind nicht automatisch besser als neun','Verwende die zentralen eigenen Jahresannahmen: P zehn Prozent bei fünfundzwanzig Prozent Risiko; Markt neun Prozent bei zwanzig Prozent Risiko; sicher drei Prozent.',[
   F('S_P=\\frac{0{,}10-0{,}03}{0{,}25}=0{,}28,\\qquad S_M=\\frac{0{,}09-0{,}03}{0{,}20}=0{,}30','Die Markt-Cash-Linie ist steiler. Bei der Auswahl eines einzelnen riskanten Fonds neben Cash ist die geringere Gesamtrisikokompensation von P relevant.',[['S_P,S_M','Erwartete Sharpe Ratios von Fonds und Markt unter denselben Annahmen.']]),
   'Die Aussage setzt den passenden Einfonds-Cash-Vergleich voraus. Eine Beimischung zu einem bereits riskanten Portfolio braucht zusätzlich die gemeinsame Bewegung mit dessen Bestand. Für diesen anderen Zweck reicht eine Rangliste einzelner Sharpe Ratios nicht.'
  ],'Sharpe ist dimensionslos und periodenabhängig. Sie ist weder Rendite in Prozent noch Wahrscheinlichkeit, Geld zu verdienen.')
 ]),
 S('sharpe-scaling','Zeitabhängigkeit, wechselnde Zinsen und negative Überschüsse','i',[
  F('\\sigma_D^2=\\sigma_P^2+\\sigma_f^2-2\\operatorname{Cov}(R_P,R_f)','Wenn Vergleichsrenditen innerhalb einer historischen Zeitreihe schwanken, ist die Streuung der Differenz nicht generell gleich der Streuung des Fonds. Berechne deshalb die tatsächliche Differenzreihe.',[['D','Fondsrendite abzüglich der Vergleichsrendite.'],['\\sigma_D^2,\\sigma_P^2,\\sigma_f^2','Varianzen der Differenz-, Fonds- und Vergleichsrendite in derselben Stichprobe beziehungsweise Modellverteilung.'],['\\operatorname{Cov}(R_P,R_f)','Zeitlich passende Fonds-Vergleichskovarianz.'],['R_P,R_f','Fonds- und Vergleichsrendite derselben Periode.']]),
  F('S_h=\\sqrt h\\,S_1','Diese Skalierung gilt für eine Summe h gleich verteilter, zeitlich unkorrelierter Differenzrenditen mit gleicher Varianz. Bei Aufzinsung, Autokorrelation oder wechselnden Parametern ist sie keine allgemeine exakte Umrechnung.',[['S_h,S_1','Sharpe Ratios für die Renditesumme über h Perioden und eine einzelne Periode.'],['h','Positive Zahl gleichartiger Perioden.']]),
  'Bei negativem Zähler kann zusätzliche Volatilität eine negative Sharpe-Zahl näher an null bringen. Daraus folgt keine allgemeine ökonomische Verbesserung. Ein Anleger mit Zugang zur sicheren Anlage muss solche Fonds nicht allein aufgrund dieser Rangfolge wählen. Null Streuung macht den Quotienten undefiniert; es wird nicht einfach Sharpe null eingesetzt.',
  'Gebühren, Bewertungs-Glättung, seltene schwere Verluste und Datenwahl können Kennzahlen verändern. Normalverteilung ist nicht nötig, um eine Sharpe-Zahl auszurechnen. Sie oder andere Verteilungs- und Nutzenannahmen können aber nötig sein, um aus zwei Momenten ein umfassendes Qualitätsurteil abzuleiten.'
 ]),
 S('treynor','Treynor bewertet Überschussrendite pro Marktbeta','i',[
  F('T_P=\\frac{\\mu_P-r_f}{\\beta_P},\\qquad T_M=\\mu_M-r_f','Treynor ersetzt Gesamtvolatilität durch Beta. Für das Marktportfolio selbst ist Beta eins. Der übliche direkte Höher-ist-besser-Vergleich setzt sinnvoll positive Betas und einen passenden gemeinsamen Marktbezug voraus.',[['T_P,T_M','Treynor-Maße für P und Markt; Renditeeinheiten je Betaeinheit.'],['\\mu_P,\\mu_M','Konsistente erwartete oder historische arithmetische Renditen.'],['r_f','Passender sicherer Satz.'],['\\beta_P','Von null verschiedenes Beta; die klassische Ranginterpretation hier für positives Beta.']]),
  X('Gleiches Portfolio, anderer Risikonenner','P besitzt Überschussrendite sieben Prozentpunkte und Beta 1,1. Der Markt besitzt Überschussrendite sechs Prozentpunkte und Beta eins.',[
   F('T_P=\\frac{0{,}07}{1{,}1}\\approx0{,}063636,\\quad T_M=0{,}06','P liefert rund 6,3636 Prozent Rendite je Betaeinheit und liegt damit über dem Marktvergleich. Seine Sharpe Ratio war trotzdem niedriger.',[['T_P,T_M','Treynor-Maße in Renditeeinheiten pro Beta.']]),
   'Das ist bei relevantem zusätzlichem Reststreuungsrisiko möglich. Ein stark konzentrierter Anleger darf dieses Risiko nicht aus seiner Entscheidung streichen, nur weil Treynor es nicht im Nenner verwendet.'
  ],'Beta null erzeugt Division durch null. Bei negativen Betas kann die Rangrichtung des Quotienten irreführen; Alpha und der wirtschaftliche Absicherungsbeitrag müssen getrennt betrachtet werden.'),
  plot('treynor-beta','Ein kleiner Betanenner kann Treynor stark erhöhen','Eigene Überschussrendite konstant sieben Prozentpunkte, positives Beta zwischen 0,1 und drei. Marktvergleich sechs Prozentpunkte bei Beta eins.','Die Kurve wird nahe Beta null sehr groß, obwohl die angenommene Überschussrendite unverändert bleibt. Das macht eine Betaschätzung mit hoher Unsicherheit besonders folgenreich. Null und negative Betas sind keine Fortsetzung der üblichen positiven Rangregel.',[.1,3],[0,75],'Positives Marktbeta','Rendite je Betaeinheit (%)',[{name:'Treynor bei fester Fondsprämie',points:grid(.1,3,100,b=>7/b)},{name:'Marktvergleich: sechs Prozent',points:[[.1,6],[3,6]],dash:true}])
 ]),
 S('m2','M² aus einer tatsächlich skalierten Cash-Fonds-Mischung ableiten','i',[
  'Das M²-Niveau ist die Rendite der auf Benchmarkrisiko skalierten Cash-Fonds-Mischung. Die M²-Differenz ist der Abstand dieses Niveaus zur Benchmarkrendite. Beide Angaben werden deshalb ausdrücklich mit ihrer Konvention bezeichnet.',
  F('a=\\frac{\\sigma_M}{\\sigma_P},\\quad R_A=(1-a)r_f+aR_P,\\quad\\mu_A=r_f+S_P\\sigma_M','Der Fondsanteil wird so gewählt, dass die vollständige Mischung die Benchmarkstandardabweichung besitzt. Das setzt positive Fondsvolatilität und die passende Cash-Finanzierung voraus.',[['a','Fondsgewicht in der risikonormierten Mischung, bei a über eins mit Kredit.'],['R_A,R_P','Zufällige Renditen der skalierten Mischung und des Fonds.'],['\\mu_A','Erwartete Rendite der risikonormierten Mischung.'],['\\sigma_M,\\sigma_P','Benchmark- und positive Fondsstandardabweichung.'],['r_f','Sicherer Anlage- und Kreditzins.'],['S_P','Sharpe Ratio des Fonds.']]),
  F('M_P^{2,L}=r_f+S_P\\sigma_M,\\qquad M_P^{2,\\Delta}=M_P^{2,L}-\\mu_M=(S_P-S_M)\\sigma_M','Die Literatur und Lernmaterialien verwenden M² teils für das risikoadjustierte Renditeniveau, teils für dessen Abstand zur Benchmark. Hier werden beide ausdrücklich getrennt und beschriftet.',[['M_P^{2,L}','Risikoadjustiertes Renditeniveau nach Skalierung auf Benchmarkrisiko.'],['M_P^{2,\\Delta}','Abstand dieses Niveaus zur Benchmarkrendite, eine Renditedifferenz.'],['r_f','Sicherer Satz.'],['S_P,S_M','Sharpe Ratios von Fonds und Benchmark bei gemeinsamen Annahmen.'],['\\sigma_M,\\mu_M','Benchmarkstandardabweichung und Benchmarkrendite.']]),
  X('Zwanzig Prozent Cash statt gleicher Betas','P schwankt mit fünfundzwanzig Prozent; Benchmarkrisiko zwanzig Prozent. Sichere Anlage drei Prozent, P-Rendite zehn Prozent und Benchmarkrendite neun Prozent.',[
   F('a=0{,}20/0{,}25=0{,}8,\\quad M_P^{2,L}=0{,}03+0{,}8(0{,}10-0{,}03)=0{,}086,\\quad M_P^{2,\\Delta}=-0{,}004','Achtzig Prozent P und zwanzig Prozent Cash liefern 8,6 Prozent erwartete Rendite bei Marktvolatilität. Der Abstand zum Markt beträgt minus 0,4 Prozentpunkte.',[['a','Fondsgewicht nach Risikonormierung.'],['M_P^{2,L}','Risikoadjustiertes Renditeniveau.'],['M_P^{2,\\Delta}','Renditedifferenz gegenüber neun Prozent Benchmark.']]),
   'Die Anteile wurden anhand der Gesamtvolatilität gewählt. Das normierte Beta ist nur 0,88. M² stellt also Gleichheit des Gesamtstandardabweichungsmaßes her, keine Gleichheit aller Risiken oder Zahlungsprofile.'
  ],'Bei gleicher Benchmark und Finanzierung ordnen Sharpe und M² die Fonds gleich. Eine abweichende Rangfolge weist auf andere Eingaben oder Konventionen hin.'),
  D('Wenn zur Risikonormierung Kredit erforderlich wäre',[
   F('\\mu_A=a\\mu_P-(a-1)r_b\\quad(a>1)','Ein höherer tatsächlicher Kreditzins vermindert die erreichbar finanzierte Rendite gegenüber der einfachen M²-Formel mit einheitlichem sicherem Satz. Die mathematische Standardkennzahl ist dann nicht automatisch eine umsetzbare Strategie.',[['\\mu_A,\\mu_P','Erwartete Rendite der skalierten Position und des Fonds.'],['a','Zur Risikonormierung benötigter Fondsanteil oberhalb eins.'],['r_b','Tatsächlicher Kreditzins.']])
  ])
 ]),
 S('jensen','Jensen-Alpha ist ein Abstand zu einer bedingten Renditeforderung','d h i',[
  F('\\alpha_P=\\mu_P-\\bigl[r_f+\\beta_P(\\mu_M-r_f)\\bigr]','Die Rendite des Fonds wird mit der Renditeforderung für sein Marktbeta verglichen. Die Klammer muss vollständig abgezogen werden.',[['\\alpha_P','Jensen-Alpha als erwartete oder passend geschätzte Renditedifferenz.'],['\\mu_P,\\mu_M','Fonds- und Marktrendite auf derselben Grundlage.'],['r_f','Sicherer Vergleichssatz.'],['\\beta_P','Fondsbeta zum verwendeten Markt.']]),
  F('a_P=\\mu_P-\\beta_P\\mu_M,\\qquad\\alpha_P=a_P-(1-\\beta_P)r_f','Ein Intercept aus einer Regression roher Renditen ist nicht schon Jensen-Alpha. Bei konstantem sicherem Satz führt das Umformen zur gezeigten Korrektur.',[['a_P','Intercept des Marktmodells mit rohen Renditen.'],['\\alpha_P','Intercept des entsprechenden Überschussrenditemodells beziehungsweise Jensen-Alpha unter konsistenten Eingaben.'],['\\mu_P,\\mu_M','Renditemittelwerte.'],['r_f','Über die verglichene Modellstichprobe konstanter sicherer Satz.'],['\\beta_P','Passendes Beta; bei zeitlich wechselnden sicheren Sätzen nicht ohne weitere Prüfung zwischen roher und Überschussregression gleichsetzen.']]),
  X('Ein kleiner Roh-Intercept ist nicht das ganze Alpha','Zentrale Jahresannahmen P zehn Prozent, Markt neun Prozent, sicher drei Prozent und Beta 1,1.',[
   F('a_P=0{,}10-1{,}1(0{,}09)=0{,}001,\\qquad\\alpha_P=0{,}001-(1-1{,}1)(0{,}03)=0{,}004','Der Roh-Intercept beträgt 0,1 Prozentpunkte, Jensen-Alpha 0,4 Prozentpunkte. Der Unterschied folgt aus der sicheren Komponente und nicht aus einem anderen Fonds.',[['a_P','Roh-Intercept.'],['\\alpha_P','Jensen-Alpha in Dezimalrenditeeinheiten.']]),
   'Ein positives geschätztes Alpha kann auf Können, Zufall, ein ungeeignetes Marktmodell oder ausgelassene gemeinsame Faktoren zurückgehen. Es muss nach Kosten, mit Unsicherheit und außerhalb der für die Strategieauswahl genutzten Daten geprüft werden.'
  ],'Historisches Alpha wird nicht allein deshalb zu zukünftigem Könnensertrag, weil es mit mehreren Nachkommastellen geschätzt wurde.')
 ]),
 S('coherent-case','Vier Maße am selben Fonds gemeinsam interpretieren','h i',[
  T(['Größe','Fonds P','Markt oder Vergleich','Was sich daraus ergibt'],[['Rendite','10 %','9 %','P besitzt höhere eigene Renditeerwartung.'],['Gesamtvolatilität','25 %','20 %','P besitzt auch höhere Gesamtstreuung.'],['Marktbeta','1,1','1','P trägt mehr lineares Marktrisiko.'],['Sharpe','0,28','0,30','P ist im Einfonds-Cash-Vergleich schlechter.'],['Treynor','6,3636 % je Beta','6 % je Beta','P besitzt die höhere Prämie pro positivem Beta.'],['M²-Niveau','8,6 %','9 %','Auf Marktvolatilität skaliert liegt P darunter.'],['M²-Differenz','−0,4 Prozentpunkte','0','Der Sharpe-Abstand bleibt erhalten.'],['Jensen-Alpha','+0,4 Prozentpunkte','0','Die eigene Rendite liegt über der CAPM-Forderung.']],'Einheit, Nenner und Vergleichsfrage sind in jeder Zeile angegeben. Die Ergebnisse stammen aus demselben eigenen Eingabesatz.'),
  'Der entscheidende Unterschied ist zusätzliche Restvarianz. Treynor und Jensen messen relativ zum Marktbeta. Sharpe und M² belasten dagegen die gesamte Streuung. Für einen allein gehaltenen konzentrierten Fonds ist diese zusätzliche Streuung wirtschaftlich relevant.',
  'Der Eingabesatz mit positivem erwartetem Jensen-Alpha ist eine eigene Analyseabweichung gegenüber dem CAPM. Er wird ausdrücklich nicht als vollständig bepreistes CAPM-Gleichgewicht ausgegeben. Im tatsächlichen CAPM-Gleichgewicht wäre erwartetes Jensen-Alpha null. Bei einer zukünftigen realisierten Stichprobe darf geschätztes Alpha dennoch zufällig von null abweichen.'
 ]),

 S('metric-connections','Die vier Maße algebraisch verknüpfen','h i',[
  F('\\alpha_P=\\beta_P(T_P-T_M),\\qquad T_P-T_M=\\alpha_P/\\beta_P','Setze die Definition der Betaprämie in Jensen-Alpha ein. Bei positivem Beta sind ein höherer Treynor-Wert als der Markt und positives Jensen-Alpha äquivalente Vorzeichenaussagen. Bei negativem Beta kehrt sich diese Rangrichtung um.',[['\\alpha_P','Jensen-Alpha.'],['\\beta_P','Von null verschiedenes Fondsbeta.'],['T_P,T_M','Treynor-Maße von Fonds und Markt auf derselben Grundlage.']]),
  F('M_P^{2,\\Delta}=\\frac{\\sigma_M}{\\sigma_P}\\alpha_P-(\\mu_M-r_f)(1-\\rho_{PM})','Ersetze die Fondsprämie in der M²-Differenz durch Betaprämie plus Alpha. Nutze anschließend Beta mal Marktvolatilität geteilt durch Fondsvolatilität gleich Korrelation. Der zweite Term erklärt, warum positives Alpha allein kein positives M² garantiert.',[['M_P^{2,\\Delta}','M²-Renditedifferenz gegenüber der Benchmark.'],['\\sigma_M,\\sigma_P','Positive Markt- und Fondsstandardabweichung.'],['\\alpha_P','Jensen-Alpha in Dezimalrenditeeinheiten.'],['\\mu_M,r_f','Marktrendite und konstanter sicherer Satz.'],['\\rho_{PM}','Korrelation des Fonds mit demselben Markt.']]),
  X('Das Vorzeichen des zentralen Vergleichs vollständig erklären','Verwende Alpha 0,004, Volatilitätsverhältnis Markt zu P 0,8, Marktprämie 0,06 und Korrelation 0,88.',[
   F('M_P^{2,\\Delta}=0{,}8(0{,}004)-0{,}06(1-0{,}88)=0{,}0032-0{,}0072=-0{,}004','Der skalierte Alpha-Beitrag beträgt plus 0,32 Prozentpunkte. Der zweite Beitrag beträgt minus 0,72 Prozentpunkte. Zusammen entstehen minus 0,4 Prozentpunkte M²-Differenz.',[['M_P^{2,\\Delta}','Renditedifferenz nach Angleichung des Gesamtvolatilitätsmaßes.']]),
   'Damit sind die gegensätzlichen Aussagen keine bloße Tabellenbeobachtung mehr. Sie folgen rechnerisch aus den unterschiedlichen Risikonennern und der Fonds-Marktkorrelation.'
  ],'Der Zusammenhang gilt bei denselben Renditen, demselben Markt und demselben konstanten sicheren Satz; andere Inputs sind kein fairer algebraischer Vergleich.')
 ]),
 S('residual-comparison','Nur die Reststreuung ändern: was bleibt gleich?','c i',[
  F('\\sigma_P(e)=\\sqrt{\\beta_P^2\\sigma_M^2+e^2},\\quad M_P^{2,L}(e)=r_f+\\frac{\\mu_P-r_f}{\\sigma_P(e)}\\sigma_M','Die zusätzliche Residualstandardabweichung verändert die Gesamtrisikokennzahl, während Beta und die vorgegebene Rendite unverändert bleiben.',[['e','Nichtnegative Residualstandardabweichung, mit dem Markt unkorreliert.'],['\\sigma_P(e)','Daraus folgende Gesamtstandardabweichung.'],['M_P^{2,L}(e)','Risikoadjustiertes Renditeniveau.'],['\\beta_P,\\sigma_M','Festes Fondsbeta und Marktstandardabweichung.'],['\\mu_P,r_f','Festgehaltene Fondsrendite und sicherer Satz.']]),
  plot('residual-m2','Zusätzliche Reststreuung senkt hier die Gesamtrisikokompensation','Eigene Annahmen P-Rendite 10 %, Beta 1,1, Marktvolatilität 20 %, sicher 3 % und Marktrendite 9 %. Nur die Restvolatilität wird zwischen null und vierzig Prozent variiert.','Ohne Reststreuung liegt die normierte Fondsrendite oberhalb der Marktannahme. Mit zunehmender Reststreuung fällt sie darunter. Jensen-Alpha bleibt in diesem Parametervergleich 0,4 Prozentpunkte, da seine Inputs unverändert bleiben.',[0,40],[5,10],'Zusätzliche Restvolatilität (%)','M²-Niveau beziehungsweise Markt (%)',[
   {name:'M²-Niveau von P',points:grid(0,40,120,e=>3+7/Math.hypot(22,e)*20)},
   {name:'Marktvergleich neun Prozent',points:[[0,9],[40,9]],dash:true}
  ]),
  X('Die scheinbar kleine Restvarianz hat eine konkrete Bedeutung','Marktfaktorstandardabweichung zweiundzwanzig Prozent, gesamte Fondsstandardabweichung fünfundzwanzig Prozent.',[
   F('v_{\\varepsilon,pp}=25^2-22^2=141,\\quad e_{pp}=\\sqrt{141}\\approx11{,}8743','Das Labor verwendet die Restvarianz in quadrierten Prozentpunkten als Eingabe, damit der Ausgangsfall mit genau fünfundzwanzig Prozent Gesamtrisiko konsistent ist. 141 sind keine 141 Prozent Volatilität.',[['v_{\\varepsilon,pp}','Restvarianz in quadrierten Prozentpunkten.'],['e_{pp}','Residualstandardabweichung in Prozentpunkten; geteilt durch hundert ergibt sie den Dezimalwert.']]),
   'Wird im Labor ausschließlich diese Restvarianz auf null gesetzt, sinkt das Gesamtrisiko auf zweiundzwanzig Prozent. Fondsrendite, Beta und CAPM-Renditeforderung bleiben fest. Es ändert sich also nicht heimlich auch die Marktexposition.'
  ],'Ein kontrollierter Vergleich hält alle anderen Annahmen fest und zeigt deshalb einen ökonomischen Zusammenhang.')
 ]),
 S('existing-portfolio','Eine Beimischung braucht die Beziehung zum bereits gehaltenen Portfolio','c h i',[
  'Die Auswahl eines einzigen riskanten Fonds neben Cash ist eine andere Aufgabe als die Ergänzung eines bestehenden Marktportfolios. Ein etwas niedrigerer eigenständiger Sharpe-Wert schließt einen nützlichen Beitrag zur vorhandenen Mischung nicht aus.',
  F('\\mu_C=(1-w)\\mu_M+w\\mu_P,\\quad\\sigma_C^2=\\bigl[1+w(\\beta_P-1)\\bigr]^2\\sigma_M^2+w^2\\sigma_\\varepsilon^2','Schreibe P als Marktbelastung plus mit dem Markt unkorreliertem Rest. Die vollständige Mischung besitzt das angegebene Gesamtbeta; nur der Fondsanteil trägt den zusätzlichen Rest.',[['w','Anfangsgewicht von P, hier zwischen null und eins.'],['\\mu_C,\\sigma_C^2','Erwartete Rendite und Varianz der Mischung aus Markt und P.'],['\\mu_M,\\mu_P','Vorgegebene Markt- und Fondsrenditen.'],['\\beta_P','Fondsbeta.'],['\\sigma_M^2,\\sigma_\\varepsilon^2','Markt- und Residualvarianz bei Markt-Residual-Kovarianz null.']]),
  X('Zwanzig Prozent P können im Analysefall nützlich sein','Achtzig Prozent Markt, zwanzig Prozent zentraler Fonds P. Verwende Markt neun Prozent, P zehn Prozent, Marktvarianz 0,04, Beta 1,1, Residualvarianz 0,0141 und sicher drei Prozent.',[
   F('\\mu_C=0{,}8(0{,}09)+0{,}2(0{,}10)=0{,}092,\\quad\\sigma_C=\\sqrt{1{,}02^2(0{,}04)+0{,}2^2(0{,}0141)}\\approx20{,}5378\\%','Das Gesamtbeta beträgt 1,02. Die höhere Erwartung wird mit leicht höherer Gesamtstreuung verglichen.',[['\\mu_C,\\sigma_C','Erwartete Rendite und Standardabweichung der Markt-P-Mischung.']]),
   F('S_C=\\frac{0{,}092-0{,}03}{\\sqrt{0{,}04218}}\\approx0{,}3019>0{,}30','Die Mischung erreicht unter diesen eigenen Analyseannahmen einen geringfügig höheren Sharpe-Wert als der Markt allein. Das demonstriert einen Ergänzungsnutzen trotz P-Sharpe 0,28.',[['S_C','Sharpe Ratio der angegebenen Mischung.']]),
   'Das Ergebnis setzt die bewusst vom CAPM abweichende P-Prognose voraus. Es ist kein Nachweis einer sicheren realen Handelsverbesserung und keine Widerlegung der CAPM-Logik unter deren eigenen Gleichgewichtsannahmen.'
  ],'Eine Rangliste eigenständiger Fonds ignoriert ihre Korrelation mit dem bereits gehaltenen Vermögen.'),
  plot('mixture-sharpe','Die Mischung kann besser sein als beide isolierten Rangurteile vermuten lassen','Eigene zentrale Analyseannahmen einschließlich positivem prognostiziertem Alpha von P. Der sichere Zins beträgt drei Prozent; P-Gewicht null bedeutet ausschließlich Markt.','Eine kleine P-Beimischung verbessert hier den Sharpe-Wert leicht. Zu viel P erhöht die Reststreuung und senkt ihn schließlich bis auf 0,28. Die Kurve zeigt die Wirkung der angenommenen gemeinsamen Risikostruktur, keine empirische optimale Quote.',[0,100],[.275,.305],'Anfangsgewicht von P (%)','Sharpe Ratio',[
   {name:'Markt-P-Mischung',points:grid(0,100,120,z=>{const w=z/100;return(.06+.01*w)/Math.sqrt((1+.1*w)**2*.04+w*w*.0141);})},
   {name:'Markt allein',points:[[0,.30],[100,.30]],dash:true}
  ])
 ]),
 S('costs','Kosten, Auswahl und Messdefinition können Alpha verändern','h i',[
  F('\\alpha_P^{net}=\\alpha_P^{gross}-c,\\quad S_P^{net}=\\frac{\\mu_P^{gross}-c-r_f}{\\sigma_P}','In diesem vereinfachten Vergleich ist c ein sicherer proportionaler Periodenkostenabzug vom Anfangskapital, der die Renditeerwartung um denselben Betrag senkt und die Varianz nicht verändert. Andere Gebühren- oder Handelskostenmodelle können anders wirken.',[['\\alpha_P^{net},\\alpha_P^{gross}','Jensen-Alpha nach und vor dem fest vorgegebenen Kostenabzug.'],['S_P^{net}','Sharpe Ratio nach diesem Abzug.'],['\\mu_P^{gross}','Rendite vor Kosten.'],['c','Sicherer Kostenabzug in Dezimalrenditeeinheiten.'],['r_f,\\sigma_P','Sicherer Satz und unveränderte positive Gesamtstandardabweichung.']]),
  X('Ein positiver Bruttowert überlebt nicht jeden Kostenabzug','P besitzt Brutto-Alpha 0,4 Prozentpunkte. Ein hier als sicher angenommener jährlicher Kostenabzug beträgt 0,6 Prozent des Anfangskapitals.',[
   F('\\alpha_P^{net}=0{,}004-0{,}006=-0{,}002','Das Netto-Alpha ist minus 0,2 Prozentpunkte. Eine Auswahl anhand der Bruttozahl allein würde diesen Unterschied übersehen.',[['\\alpha_P^{net}','Netto-Jensen-Alpha im ausdrücklich vereinfachten Kostenmodell.']]),
   'Daten müssen deshalb Kostenbasis, Renditeart, betrachteten Anleger und Benchmark berücksichtigen. Transaktionskosten können mit Marktstress und Handelshäufigkeit zusammenhängen; sie sind dann kein bloß konstanter Abzug mehr.'
  ],'Brutto- und Nettokennzahlen oder verschiedene Währungen werden nicht als scheinbar identische Vergleichsgrößen nebeneinander gestellt.')
 ]),
 S('limitations','Was diese Kennzahlen nicht beweisen','d f h i',[
  'Varianz und lineares Beta erfassen nicht die gesamte Verteilung. Zwei Fonds mit gleicher Sharpe Ratio können unterschiedliche Schiefe, maximale Verluste, Liquidität, Ausfall- oder Gegenparteirisiken besitzen. Geglättete illiquide Bewertungen können die geschätzte Streuung verkleinern, ohne die wirtschaftlichen Verlustquellen zu beseitigen.',
  'Der wahre theoretische Markt umfasst alle relevanten riskanten Vermögenswerte, nicht nur einen frei gewählten Aktienindex. Eine empirische CAPM-Prüfung benutzt eine Marktvertretung. Ein auffälliges Alpha kann deshalb gleichzeitig eine Aussage über diese Vertretung, das Messverfahren und das Renditemodell sein.',
  'Mehrfaktormodelle können eine bislang im Rest verborgene gemeinsame Exposition erklären. Ein Alpha relativ zum Einindexmodell muss nicht auch relativ zu einem geeigneten Mehrfaktormodell bestehen. Die Wahl des Modells gehört zur Interpretation und darf nicht erst nach Sichtung eines gewünschten Ergebnisses opportunistisch geändert werden.',
  D('Vertiefung: Schätzunsicherheit von Alpha',[
   'Ein Regressionsintercept wird zusammen mit seiner Unsicherheit beurteilt. Die üblichen OLS-Standardfehler verlangen passende Fehlerannahmen; Heteroskedastizität und zeitliche Abhängigkeit können andere Standardfehler nötig machen. Ein hoher t-Wert aus vielen ausprobierten Strategien beseitigt die Auswahlverzerrung nicht.',
   'Die vorherigen Regressionsabschnitte zeigen einen separaten eigenen Datensatz mit Schätzrechnung. Seine historischen Größen werden nicht still mit dem prognostizierten zentralen P-Satz vermischt. Eine statistisch auffällige Vergangenheitsabweichung bleibt eine andere Aussage als eine bewiesene zukünftige Fähigkeit.'
  ])
 ]),
 shared('estimation','e h i'),
 S('calculator','Im Labor den Risikonenner und das Marktmodell auseinanderhalten','a b c d e f g h i',[
  'Der Performance-Rechner zeigt den zentralen Fall und zwölf klar bezeichnete Vergleiche. Fondsrendite, sicherer Zins, Marktrendite, positives Beta, Marktvolatilität und zusätzliche Restvarianz sind die Eingaben. Die Gesamtvolatilität wird daraus konsistent berechnet. Dadurch können keine unmöglichen Kombinationen aus Beta und frei eingegebener zu kleiner Gesamtvolatilität entstehen.',
  'Setze zunächst nur die Restvarianz auf null. Sharpe und M² verbessern sich bei der positiven Fondsprämie, Jensen und Treynor bleiben gleich. Erhöhe anschließend nur die Markterwartung: Das erforderliche CAPM-Niveau und Alpha ändern sich, die eigene Sharpe Ratio bleibt gleich. Die M²-Differenz ändert sich, während das M²-Niveau unverändert bleibt.',
  'Der Rechner verwendet ausdrücklich positive Betas. Null- und negative-Beta-Grenzfälle werden im Text erläutert; der separate CAPM-Rechner erlaubt auch negative Betas. Der Performance-Rechner ist eine deterministische Auswertung eigener Annahmen, kein Renditeprognosemodell und keine automatische Prüfung eines vollständigen Kapitalmarktgleichgewichts.',
  'Eine Tabelle isoliert die Wirkung verschiedener Restvolatilitäten bei sonst gleichen Eingaben. Die Kurven zeigen das M²-Niveau und die Marktrendite auf derselben Renditeskala. Historische Daten, Gebühren, Steuern und Zufallspfade werden nicht zusätzlich verborgen geschätzt.'
 ]),
 S('workflow','Eine belastbare Analyse in der richtigen Reihenfolge','a b c d e f g h i',[
  T(['Prüfungsschritt','Praktische Kontrolle'],[['Frage bestimmen','Standalone-Fonds, Ergänzung eines Bestands, Preisschätzung oder historische Managerbeurteilung?'],['Daten vereinheitlichen','Zeitraum, Währung, Total Return, Kosten und Vergleichsanlage passend festlegen.'],['Modell prüfen','Marktvertretung, Finanzierung, Beta, Residualannahmen und gemeinsame Kovarianzstruktur plausibilisieren.'],['Rechnen und gegenprüfen','Varianzen addieren, Volatilität erst anschließend ziehen; Roh- und Überschussintercept unterscheiden.'],['Vergleichen','Sharpe mit M²-Rang vergleichen, Jensen mit Treynor bei positiven Betas verbinden; ungleiche Nenner erklären.'],['Grenzen offenhalten','Schätzfehler, Auswahl, Liquidität, Tail-Risiko und Umsetzbarkeit separat beurteilen.']],'Ein Kennzahlenvergleich ist erst nachvollziehbar, wenn die Ausgangsfrage und die Annahmen mitgeliefert werden.')
 ]),
 S('review','Verständnis, Transfer und typische Fehlurteile','a b c d e f g h i',[
  ...[
   ['Warum muss die sichere Anlage zur Währung und zum Horizont passen?','Ein festes Nominalversprechen in anderer Währung oder zu einem anderen Termin sichert den relevanten Endwert nicht.'],
   ['Warum hat eine Cash-Markt-Mischung bei negativem Marktgewicht trotzdem positive Volatilität?','Die Schwankung skaliert mit dem Betrag des riskanten Gewichts. Das Vorzeichen verändert die Richtung der Exposition, nicht die Nichtnegativität des Risikomaßes.'],
   ['Wann wird die CAL zu einer geknickten Linie?','Wenn zusätzliche Kreditfinanzierung einen anderen Zins als die sichere Geldanlage kostet. Die Rendite der gehebelten Position muss mit dem tatsächlichen Kreditzins gerechnet werden.'],
   ['Was macht eine beliebige CAL zur CML?','Die Identifikation ihres riskanten Portfolios als effizientes Marktportfolio unter den entsprechenden CAPM-Gleichgewichtsannahmen. Ein positiver Anstieg allein reicht nicht.'],
   ['Warum ist spezifisches Risiko nicht gleichbedeutend mit unwichtigem Risiko?','Es kann für den konzentrierten Anleger erhebliche Verluste verursachen. Die CAPM-Aussage betrifft seine zusätzliche Gleichgewichtsvergütung für breit diversifizierende Anleger.'],
   ['Wann verschwinden Residualrisiken durch viele Titel?','Im gezeigten symmetrischen Modell nur bei passenden Gewichten und hinreichend unkorrelierten Resten. Gemeinsame ausgelassene Faktoren können im Einindexrest erhalten bleiben.'],
   ['Warum dürfen Standardabweichungen von Marktfaktor und Rest nicht einfach addiert werden?','Bei unkorrelierten Komponenten addieren sich die Varianzen. Erst die Wurzel der gesamten Varianz liefert die Gesamtvolatilität.'],
   ['Warum ist Beta nicht die Korrelation?','Beta ist Korrelation multipliziert mit dem Verhältnis von Anlage- zu Marktvolatilität. Verschiedene relative Schwankungen verändern Beta auch bei gleicher Korrelation.'],
   ['Was bedeutet Beta null bei positiver Gesamtvolatilität?','Die lineare Markt-Kovarianz ist null; der Fonds kann weiterhin erhebliche andere Schwankungs- und Verlustquellen besitzen.'],
   ['Wann gilt der erklärte Varianzanteil als quadrierte Marktkorrelation?','Im passenden einfachen Einindexmodell beziehungsweise der Regression mit Intercept unter den zugehörigen Konventionen. Das erklärt keine beliebige Mehrfaktorkonstellation.'],
   ['Warum werden erwartete und historische CAPM-Eingaben nicht beliebig kombiniert?','Eine zukünftige Renditeforderung braucht zugehörige Zukunftsannahmen; historische Schätzungen sind unsichere Eingaben und müssen nicht unverändert gelten.'],
   ['Warum kann ein Punkt über der SML eine Unterbewertungsthese anzeigen?','Nur bei tragfähiger eigener erwarteter Rendite und passenden Risikoeingaben liegt diese Rendite über der Modellforderung. Ein realisierter guter Ausgang allein ist keine entsprechende Bewertungsthese.'],
   ['Warum ist P im zentralen Beispiel über der SML, aber unter der Markt-Cash-Linie?','Beta und Gesamtvolatilität sind verschiedene Risikonenner. Zusätzliche Reststreuung belastet den Gesamtvergleich; die eigene Prognose weicht außerdem ausdrücklich vom CAPM-Gleichgewicht ab.'],
   ['Warum kann der Anfangspreis beim gleichen unsicheren Endzahlungsprozess Beta verändern?','Rendite ist Endzahlung geteilt durch Anfangspreis minus eins. Bei festem Auszahlungsprozess skaliert deshalb auch die Rendite-Marktkovarianz mit dem Kehrwert des Preises.'],
   ['Welche Streuung gehört in die allgemeine historische Sharpe-Berechnung?','Die Standardabweichung derselben Differenzrenditen, deren arithmetischer Mittelwert im Zähler steht. Die rohe Fondsstandardabweichung reicht bei wechselndem Vergleichszins nicht immer aus.'],
   ['Warum ist eine höhere negative Sharpe Ratio kein allgemeines Qualitätsurteil?','Bei negativem Überschuss kann größere Volatilität den Quotienten näher an null bringen. Eine ökonomische Auswahl benötigt den konkreten Zweck und verfügbare Alternativen.'],
   ['Welche Informationen fehlen Sharpe beim Ergänzen eines vorhandenen riskanten Portfolios?','Die Beziehungen zur bestehenden Position und zu deren Risiken und Verpflichtungen. Eine niedriger eingestufte Einzelanlage kann bei geeigneter gemeinsamer Bewegung nützlich sein.'],
   ['Weshalb sind Treynor-Vergleiche bei Beta null oder negativ problematisch?','Bei null ist der Quotient undefiniert. Bei negativem Nenner kehren einfache Rang- und Vorzeichenurteile ihre Bedeutung um; Absicherung und Alpha müssen direkt geprüft werden.'],
   ['Was normiert die M²-Konstruktion?','Die Gesamtstandardabweichung des Fonds wird über Cash oder Kredit an die Benchmark angeglichen. Damit werden nicht gleichzeitig Beta, Liquidität und alle Verlustprofile identisch.'],
   ['Weshalb müssen M²-Niveau und M²-Differenz beschriftet werden?','Die eine Zahl ist die Rendite der risikonormierten Mischung, die andere ihr Abstand zur Benchmark. Beide werden in Literatur und Lernmaterial teils unter M² geführt.'],
   ['Wann ordnen Sharpe und M² dieselben Fonds gleich?','Bei derselben positiven Benchmarkvolatilität, demselben Vergleichszins und konsistenten Daten, Kosten und Perioden. M² ist dann eine positive affine Umformung von Sharpe.'],
   ['Warum ist ein Roh-Intercept von 0,1 Prozentpunkten hier nicht das Jensen-Alpha?','Die Rohregression enthält die sichere Komponente anders. Bei konstantem sicherem Satz drei Prozent und Beta 1,1 ergibt ihre Korrektur Jensen-Alpha 0,4 Prozentpunkte.'],
   ['Welche Kennzahlen ändern sich, wenn nur die Restvarianz steigt?','Bei festem Beta, Fonds- und Marktertrag und sicherem Satz bleiben Jensen und Treynor gleich. Gesamtvolatilität steigt; bei positiver Prämie sinken Sharpe und M².'],
   ['Warum ist ein positiver Alpha-Schätzer kein ausreichender Skill-Beweis?','Schätzunsicherheit, Marktvertretung, weitere Risikofaktoren, Gebühren und die Auswahl aus vielen untersuchten Strategien können das Ergebnis erklären. Eine unabhängige Nachprüfung bleibt nötig.']
  ].map(([q,a],i)=>D((i+1)+'. '+q,[a]))
 ])
],explorations:[{section:'calculator',lesson:'portfolio-14',focus:'lab',label:'Alpha, Gesamtrisiko und M² im konsistenten Vergleichslabor'},{section:'calculator',lesson:'portfolio-04',focus:'lab',label:'Negative und positive Betas in der CAPM-Renditeforderung'}],
 related:[{unit:'portfolio-risk',section:'matrix-validity',label:'Gemeinsam zulässige Kovarianzen und Portfolioeingaben'},{unit:'portfolio-risk',section:'allocation-limits',label:'Risikoaversion und tatsächliche Allokationsgrenzen'},{unit:'equity-factors',section:'model-alpha',label:'Warum weitere Faktoren ein scheinbares Alpha erklären können'},{unit:'return-statistics',section:'covariance',label:'Historische Kovarianz aus gepaarten Renditen'},{unit:'regression',section:'coefficient-tests',label:'Regressionsunsicherheit und Testannahmen'},{unit:'capital-structure',section:'market-weights',label:'Anspruch und Kapitalstruktur im Kapitalkostenansatz'}],
 sources:[{title:'CFA Institute: Level I Topic Outlines 2027, Seiten 27–28; verbindlicher Lernzielumfang von Portfolio Risk and Return: Part II',url:'https://www.cfainstitute.org/sites/default/files/2027levelitopicoutline_online.pdf#page=27'},{title:'CFA Institute: Portfolio Risk and Return: Part II, 2026; ergänzende öffentliche Konzeptübersicht, nicht der 2027-Lernzielkatalog',url:'https://www.cfainstitute.org/insights/professional-learning/refresher-readings/2026/portfolio-risk-return-part-2'},{title:'William F. Sharpe: The Sharpe Ratio, 1994, Stanford; Differenzrendite, Zeitraum und Grenzen des Einzahl-Rankings',url:'https://web.stanford.edu/~wfsharpe/art/sr/SR.htm'},{title:'Franco Modigliani und Leah Modigliani: Risk-adjusted performance, Journal of Portfolio Management 23(2), 1997; Originalaufsatz zur Risikoangleichung',url:'https://tsgperformance.com/wp-content/uploads/2020/11/modigliani-modigliani.pdf'}],review:{status:'draft',date:'2026-10-26',note:'Eigene konsistente Risiko- und Performancevergleiche, ausdrücklich getrennte erwartete und historische Größen. CAPM-Theorie und historische Regressionsherleitungen werden aus dem Grundlagenkapitel kopiert und unter den Portfolio-Lernzielen vertieft; keine Mutation des dortigen Inhalts. Fachliche Gesamtabnahme bleibt ausstehend.'}};

